<?php $pageTitle='Pelanggan Billing';$activeMenu='billing';$billingView='customers'; ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pelanggan Billing - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css?v=12"><link rel="stylesheet" href="../assets/css/common.css?v=12"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><link rel="stylesheet" href="../assets/css/billing_customer_pro.css?v=2"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"></head><body><?php require_once '../includes/sidebar.php';?><div class="main"><main class="cp-page"><header><div><h1>Pelanggan Billing</h1><p>Kelola pelanggan, akun PPPoE, paket, harga, dan status billing.</p></div><button id="add" class="primary"><i class="bi bi-person-plus"></i> Tambah Pelanggan</button></header><section class="cp-kpis"><div><span>Total</span><b id="total">0</b></div><div><span>Aktif</span><b id="active">0</b></div><div><span>Ditangguhkan</span><b id="suspended">0</b></div></section><section class="cp-card"><div class="cp-filter"><input id="search" placeholder="Cari nama, PPPoE, paket, HP..."><select id="status"><option value="all">Semua Status</option><option value="active">Aktif</option><option value="suspended">Ditangguhkan</option></select></div><div class="cp-table"><table><thead><tr><th>Pelanggan</th><th>PPPoE</th><th>Paket</th><th>Harga</th><th>Jatuh Tempo</th><th>Piutang</th><th>Status</th><th>Aksi</th></tr></thead><tbody id="rows"><tr><td colspan="8">Menghubungkan ke database...</td></tr></tbody></table></div></section></main></div><div id="modal" class="cp-modal" hidden><div class="cp-dialog"><div class="cp-head"><h2 id="title">Tambah Pelanggan</h2><button id="close">×</button></div><form id="form"><input type="hidden" name="id"><div class="cp-grid"><label>Nama<input name="name" required></label><label>No. HP<input name="phone"></label><label>Username PPPoE<select name="pppoe_username" id="pppoe" required><option value="">Memuat...</option></select></label><label>Nama Paket<input name="package_name" required></label><label>Harga Bulanan<input name="monthly_price" type="number" min="0" step="1000" required></label><label>Tanggal Tagihan<input name="billing_day" type="number" min="1" max="31" value="10" required></label><label>Status<select name="status"><option value="active">Aktif</option><option value="suspended">Ditangguhkan</option></select></label><label class="full">Alamat<textarea name="address"></textarea></label><label class="full">Catatan<textarea name="notes"></textarea></label></div><div id="error" hidden></div><footer><button type="button" id="cancel">Batal</button><button class="primary">Simpan</button></footer></form></div></div><script src="../assets/js/billing_customer_pro.js?v=3"></script><script src="../assets/js/app.js?v=1"></script><script>setTimeout(async function(){const r=document.getElementById('rows');if(!r||!/^Menghubungkan ke database|Memuat data pelanggan/.test(r.textContent.trim()))return;try{const z=await fetch('../api/billing_customers_pro.php?action=list&t='+Date.now(),{cache:'no-store'}),d=await z.json();if(!d.success)throw Error(d.message||'API gagal');document.getElementById('total').textContent=d.summary.total||0;document.getElementById('active').textContent=d.summary.active||0;document.getElementById('suspended').textContent=d.summary.suspended||0;const esc=v=>{const x=document.createElement('span');x.textContent=v??'-';return x.innerHTML},rp=v=>'Rp '+Number(v||0).toLocaleString('id-ID');r.innerHTML=(d.customers||[]).map(x=>`<tr><td><b>${esc(x.name)}</b><small>${esc(x.phone)}</small></td><td><b>${esc(x.pppoe_username)}</b></td><td>${esc(x.package_name)}</td><td>${rp(x.monthly_price)}</td><td>Tgl ${esc(x.billing_day)}</td><td>${Number(x.unpaid_count)?`<b>${rp(x.unpaid_amount)}</b><small>${x.unpaid_count} invoice</small>`:'Rp 0'}</td><td><span class="badge ${x.status}">${x.status==='active'?'AKTIF':'DITANGGUHKAN'}</span></td><td class="actions"><a href="customer_detail_pro.php?id=${encodeURIComponent(x.id)}" title="Detail"><i class="bi bi-eye"></i></a></td></tr>`).join('')||'<tr><td colspan="8" class="empty">Belum ada pelanggan.</td></tr>'}catch(e){r.innerHTML='<tr><td colspan="8" class="empty">Gagal memuat data: '+String(e.message||e).replace(/[<>]/g,'')+'</td></tr>'}},1500);</script></body></html>